on conflict (slug) do nothing;

on conflict (slug) do nothing;

with seed(collection_slug, item_slugs) as (values
    ('travel-transport', array['journey','miss','return']::text[]),
    ('city-directions', array['crowded','distance','local']::text[]),
    ('communication', array['decide','enough','polite']::text[]),
    ('study-work', array['advantage','discover','spend']::text[]),
    ('daily-routine', array['forget','usually']::text[]),
    ('family-relations', array['invite']::text[]),
    ('b1-communication-and-work', array['announce','avoid','compare','depend','effort','explain','include','notice','prefer','reduce','achieve','although','benefit','challenge','consider','environment','improve','opportunity','reliable','require','suggest','valuable']::text[]),
    ('b2-ideas-and-evidence', array['acquire','adapt','apparent','conduct','contrast','decline','establish','imply','justify','occur','acknowledge','assess','compelling','consequence','distinguish','emerge','inevitable','maintain','substantial','tendency','undergo','whereas']::text[]),
    ('c1-precision-and-analysis', array['adjacent','concise','constraint','denote','devise','explicit','facilitate','fluctuate','refine','ambiguous','coherent','contemplate','diminish','endeavour','feasible','inherent','notwithstanding','prevalent','scrutinize','subsequent','undermine']::text[]),
    ('c2-advanced-expression', array['abstruse','assiduous','capricious','clandestine','deleterious','epistemic','inchoate','obfuscate','salient','scrupulous','acumen','ameliorate','disparate','equivocal','exacerbate','fastidious','intransigent','ostensibly','pervasive','pragmatic','ubiquitous','vindicate','nuance']::text[])
)
select seed.collection_slug, words.item_slug, words.position::integer
from seed
cross join lateral unnest(seed.item_slugs) with ordinality as words(item_slug, position)
on conflict (collection_slug, vocabulary_item_slug) do nothing;