('advantage', 'advantage', 'advantage', 'avantage', 'nom', 'A2', 'One advantage of the train is that it is fast.', 'Un avantage du train est sa rapidité.', 'Advantage est suivi de over pour comparer deux options.', array['benefit'], array['disadvantage'], array['main advantage', 'take advantage of'], array['travel', 'communication']),
('crowded', 'crowded', 'crowded', 'bondé, encombré', 'adjectif', 'A2', 'The bus is crowded during rush hour.', 'Le bus est bondé aux heures de pointe.', 'Crowded décrit un lieu rempli de personnes ou de choses.', array['packed', 'full'], array['empty'], array['crowded street', 'get crowded'], array['city', 'travel']),
('decide', 'decide', 'decide', 'décider', 'verbe', 'A2', 'We decided to visit the museum tomorrow.', 'Nous avons décidé de visiter le musée demain.', 'Decide to + infinitif; decide on + nom.', array['choose', 'make up your mind'], array['hesitate'], array['decide to go', 'decide on a plan'], array['communication', 'decisions']),
('discover', 'discover', 'discover', 'découvrir', 'verbe', 'A2', 'They discovered a quiet café near the station.', 'Ils ont découvert un café tranquille près de la gare.', 'Discover porte sur une découverte nouvelle, pas nécessairement une invention.', array['find', 'uncover'], array[]::text[], array['discover a place', 'discover that'], array['travel', 'city']),
('distance', 'distance', 'distance', 'distance', 'nom', 'A2', 'The hotel is within walking distance of the beach.', 'L’hôtel se trouve à distance de marche de la plage.', 'Distance peut être littéral ou exprimer une relation moins proche.', array['space', 'gap'], array[]::text[], array['walking distance', 'keep your distance'], array['travel', 'city']),
('enough', 'enough', 'enough', 'assez, suffisamment', 'déterminant/adverbe', 'A2', 'We have enough time to catch the train.', 'Nous avons assez de temps pour prendre le train.', 'Enough précède un nom, mais suit un adjectif ou un adverbe.', array['sufficiently', 'sufficient'], array['insufficient'], array['enough time', 'good enough'], array['communication', 'quantity']),
('forget', 'forget', 'forget', 'oublier', 'verbe', 'A2', 'Do not forget to bring your passport.', 'N’oubliez pas d’apporter votre passeport.', 'Forget to do signifie ne pas faire par oubli; forget doing signifie oublier un souvenir.', array['overlook', 'leave behind'], array['remember'], array['forget to call', 'forget about'], array['travel', 'daily-routine']),
('invite', 'invite', 'invite', 'inviter', 'verbe', 'A2', 'I invited my neighbours to dinner.', 'J’ai invité mes voisins à dîner.', 'Invite someone to an event; invite someone to do something.', array['ask', 'welcome'], array[]::text[], array['invite someone over', 'invite someone to dinner'], array['family', 'social']),
('journey', 'journey', 'journey', 'voyage, trajet', 'nom', 'A2', 'The journey takes about two hours by train.', 'Le trajet dure environ deux heures en train.', 'Journey insiste sur le déplacement; trip désigne souvent le séjour ou l’excursion.', array['trip', 'voyage'], array[]::text[], array['long journey', 'journey home'], array['travel', 'transport']),
('local', 'local', 'local', 'local, du quartier', 'adjectif/nom', 'A2', 'We asked a local for directions.', 'Nous avons demandé notre chemin à une personne du quartier.', 'Local qualifie ce qui concerne un lieu ou les personnes qui y vivent.', array['nearby', 'regional'], array['distant'], array['local area', 'local people'], array['city', 'travel']),
('miss', 'miss', 'miss', 'manquer, rater', 'verbe', 'A2', 'We missed the last bus and took a taxi.', 'Nous avons raté le dernier bus et pris un taxi.', 'Miss a bus signifie le rater; miss someone signifie ressentir son absence.', array['fail to catch', 'long for'], array['catch'], array['miss the train', 'miss a friend'], array['travel', 'feelings']),
('polite', 'polite', 'polite', 'poli, courtois', 'adjectif', 'A2', 'It is polite to say thank you after a meal.', 'Il est poli de dire merci après un repas.', 'Polite décrit les bonnes manières; courteous est plus soutenu.', array['courteous', 'respectful'], array['rude'], array['polite request', 'polite conversation'], array['communication', 'social']),
('return', 'return', 'return', 'retourner, retour', 'verbe/nom', 'A2', 'She returned home before dark.', 'Elle est rentrée avant la nuit.', 'Return to + lieu; return home ne prend pas de préposition.', array['come back', 'go back'], array['leave'], array['return home', 'return ticket'], array['travel', 'movement']),
('spend', 'spend', 'spend', 'dépenser, passer du temps', 'verbe', 'A2', 'We spent the afternoon exploring the old town.', 'Nous avons passé l’après-midi à explorer la vieille ville.', 'Spend time/money on + nom ou spend time doing + verbe en -ing.', array['use', 'pass'], array['save'], array['spend time', 'spend money on'], array['time', 'finance']),
('usually', 'usually', 'usually', 'habituellement, généralement', 'adverbe', 'A2', 'I usually walk to work when the weather is good.', 'Je vais généralement au travail à pied quand il fait beau.', 'Usually se place avant le verbe principal mais après be.', array['normally', 'generally'], array['rarely'], array['usually do', 'as usual'], array['daily-routine', 'time']),
