('include', 'include', 'include', 'inclure, comprendre', 'verbe', 'B1', 'The price includes breakfast and airport transfers.', 'Le prix comprend le petit-déjeuner et les transferts aéroport.', 'Include énumère une partie d’un ensemble; consist of décrit sa composition.', array['contain', 'involve'], array['exclude'], array['include someone in', 'price includes'], array['travel', 'work']),
