('reduce', 'reduce', 'reduce', 'réduire, diminuer', 'verbe', 'B1', 'The new system reduced waiting times.', 'Le nouveau système a réduit les temps d’attente.', 'Reduce indique une diminution; decrease peut décrire le changement sans agent explicite.', array['decrease', 'lower'], array['increase'], array['reduce costs', 'reduce the risk'], array['work', 'quantity']),
