('establish', 'establish', 'establish', 'établir, fonder', 'verbe', 'B2', 'The study established a link between sleep and memory.', 'L’étude a établi un lien entre le sommeil et la mémoire.', 'Establish insiste sur la démonstration ou la mise en place durable.', array['found', 'demonstrate'], array['disprove'], array['establish a connection', 'establish a company'], array['academic', 'work']),
('imply', 'imply', 'imply', 'impliquer, laisser entendre', 'verbe', 'B2', 'Her comments imply that further changes are planned.', 'Ses commentaires laissent entendre que d’autres changements sont prévus.', 'Imply signifie suggérer indirectement; infer décrit la conclusion tirée par l’auditeur.', array['suggest', 'indicate'], array['state explicitly'], array['imply that', 'strongly imply'], array['communication', 'academic']),
('justify', 'justify', 'justify', 'justifier', 'verbe', 'B2', 'The evidence does not justify such a strong conclusion.', 'Les éléments ne justifient pas une conclusion aussi catégorique.', 'Justify fournit une raison valable; explain peut seulement décrire une cause.', array['warrant', 'defend'], array['condemn'], array['justify a decision', 'fully justified'], array['academic', 'communication']),
